import{_ as n,C as o,o as t,c as r,a2 as s,b as d,w as a,a as l,E as c,a3 as p}from"./chunks/framework.CZqXuAiL.js";const f=JSON.parse('{"title":"SYNPROXY (scalar SYN gate)","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/detection-engine/synproxy.md","filePath":"openshield-xdp/detection-engine/synproxy.md","lastUpdated":null}'),h={name:"openshield-xdp/detection-engine/synproxy.md"};function g(k,e,u,_,y,b){const i=o("Mermaid");return t(),r("div",null,[e[1]||(e[1]=s('<h1 id="synproxy-scalar-syn-gate" tabindex="-1">SYNPROXY (scalar SYN gate) <a class="header-anchor" href="#synproxy-scalar-syn-gate" aria-label="Permalink to &quot;SYNPROXY (scalar SYN gate)&quot;">​</a></h1><p>Scalar, rate-based TCP SYN-flood mitigation that loads on <strong>every</strong> supported kernel (5.15 → latest) with zero user fixes.</p><div class="tip custom-block"><p class="custom-block-title">Design note — why rate-based, not cookie-based</p><p>Earlier designs generated SYN cookies in XDP and bounced a SYN-ACK with <code>XDP_TX</code>. That approach needs packet rewriting, checksum recomputation, and (in richer variants) helpers like <code>bpf_sk_lookup_tcp</code> / <code>bpf_tcp_gen_syncookie</code> whose verifier behaviour differs across kernels — so it failed to load on some kernels without per-kernel patching. OpenShield instead delivers SYN-flood protection through a <strong>scalar, non-terminal gate plus a per-IP SYN rate limiter</strong>. It touches no packet bytes and calls no version-specific helpers, so it verifies identically everywhere.</p></div><h2 id="what-the-gate-does" tabindex="-1">What the gate does <a class="header-anchor" href="#what-the-gate-does" aria-label="Permalink to &quot;What the gate does&quot;">​</a></h2><p>The <code>OPENSHIELD_SYNPROXY</code> build flag compiles in <code>synproxy_check_listener()</code>, an <code>__always_inline</code> hook that runs early in the pipeline:</p><ol><li>It looks <strong>only</strong> at scalar fields already extracted by <code>parse_packet</code> (<code>protocol</code>, <code>is_tcp_syn</code>) — no packet-pointer access.</li><li>For a pure TCP SYN it increments a profiling counter (<code>PROF_SYNPROXY_SYNACK</code>) and returns <code>STAGE_PASS</code>.</li><li>The baseline gate <strong>never drops</strong> — it is a cheap classification/accounting hook.</li></ol><p>The actual mitigation happens downstream in the <strong>rate-limiting stage</strong>: each source IP&#39;s SYN rate is tracked, and a source exceeding <code>syn_pps_threshold</code> accrues <code>syn_pps_score</code> toward the suspicion threshold, after which it is banned like any other abuser.</p>',7)),(t(),d(p,null,{default:a(()=>[c(i,{id:"mermaid-37",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20Client%0A%20%20%20%20participant%20OpenShield%20as%20OpenShield%20(XDP)%0A%20%20%20%20participant%20Kernel%20as%20Server%20(kernel)%0A%0A%20%20%20%20Client-%3E%3EOpenShield%3A%20SYN%20(seq%3DC)%0A%20%20%20%20Note%20over%20OpenShield%3A%20synproxy_check_listener()%3Cbr%2F%3Escalar-only%2C%20accounts%20the%20SYN%0A%20%20%20%20OpenShield-%3E%3EKernel%3A%20STAGE_PASS%20(continue%20pipeline)%0A%20%20%20%20Note%20over%20OpenShield%3A%20rate-limit%20stage%20tracks%20per-IP%20SYN%20pps%0A%20%20%20%20alt%20syn_pps%20over%20threshold%0A%20%20%20%20%20%20%20%20Note%20over%20OpenShield%3A%20suspicion_score%20%2B%3D%20syn_pps_score%20%E2%86%92%20ban%0A%20%20%20%20%20%20%20%20OpenShield--%3E%3EClient%3A%20XDP_DROP%20(subsequent%20packets)%0A%20%20%20%20else%20within%20threshold%0A%20%20%20%20%20%20%20%20OpenShield-%3E%3EKernel%3A%20XDP_PASS%20(normal%20handshake)%0A%20%20%20%20end%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s(`<h2 id="why-this-is-portable" tabindex="-1">Why this is portable <a class="header-anchor" href="#why-this-is-portable" aria-label="Permalink to &quot;Why this is portable&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Behaviour</th></tr></thead><tbody><tr><td><strong>Packet access</strong></td><td>None. Reads pre-parsed scalars only.</td></tr><tr><td><strong>Helpers</strong></td><td>None version-specific. No <code>bpf_sk_lookup_tcp</code>, no cookie crypto, no <code>XDP_TX</code>.</td></tr><tr><td><strong>Verifier</strong></td><td>Identical instruction shape on every kernel ≥ 5.15.</td></tr><tr><td><strong>Drops</strong></td><td>Baseline never drops in the gate; bans are issued by the rate limiter.</td></tr><tr><td><strong>IPv4 / IPv6</strong></td><td>Both — mitigation rides on <code>ip_stats_map</code> / <code>ip_stats_map_v6</code> SYN counters.</td></tr></tbody></table><h2 id="extending-it-opt-in-kernel-≥-6-10" tabindex="-1">Extending it (opt-in, kernel ≥ 6.10) <a class="header-anchor" href="#extending-it-opt-in-kernel-≥-6-10" aria-label="Permalink to &quot;Extending it (opt-in, kernel ≥ 6.10)&quot;">​</a></h2><p>The gate is deliberately a hook. On kernels ≥ 6.10, advanced users who build with <code>make FREPLACE=1</code> can hot-patch <code>synproxy_check_listener</code> via a freplace module to add richer listener verification (e.g. <code>bpf_sk_lookup_tcp</code> to confirm a real listening socket) <strong>without</strong> changing the portable baseline or risking load failures on other kernels. See <a href="/pingless-studios-docs/openshield-xdp/architecture/freplace">freplace</a>.</p><h2 id="tuning" tabindex="-1">Tuning <a class="header-anchor" href="#tuning" aria-label="Permalink to &quot;Tuning&quot;">​</a></h2><p>The relevant knobs live in the rate-based detection config, not in a cookie store:</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>synproxy_enabled</code></td><td><code>false</code></td><td>Enables the scalar SYN gate (accounting + freplace hook).</td></tr><tr><td><code>syn_pps_threshold</code></td><td><code>170</code></td><td>Per-IP SYN packets/sec before scoring begins.</td></tr><tr><td><code>syn_pps_score</code></td><td>—</td><td>Suspicion score added per second a source is over the SYN threshold.</td></tr></tbody></table><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dynamic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  synproxy_enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # scalar SYN gate (off by default)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">static</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  syn_pps_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">170</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # per-IP SYN pps before scoring</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  syn_pps_score</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # score added per violation</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Defense in depth</p><p>For an additional, independent layer below XDP, enable the kernel&#39;s own SYN cookies: <code>sysctl -w net.ipv4.tcp_syncookies=1</code>. This is the real Linux TCP-stack feature and complements the XDP rate-based gate.</p></div><h2 id="common-problems" tabindex="-1">Common problems <a class="header-anchor" href="#common-problems" aria-label="Permalink to &quot;Common problems&quot;">​</a></h2><h3 id="syn-floods-still-reaching-the-server" tabindex="-1">&quot;SYN floods still reaching the server&quot; <a class="header-anchor" href="#syn-floods-still-reaching-the-server" aria-label="Permalink to &quot;&quot;SYN floods still reaching the server&quot;&quot;">​</a></h3><p>Lower <code>syn_pps_threshold</code> toward your legitimate per-IP SYN rate, and ensure rate limiting is enabled. Confirm <code>xdp_mode</code> is <code>native</code> for line-rate processing. Enable kernel <code>tcp_syncookies</code> for defense in depth.</p><h3 id="legitimate-clients-getting-banned-during-traffic-spikes" tabindex="-1">&quot;Legitimate clients getting banned during traffic spikes&quot; <a class="header-anchor" href="#legitimate-clients-getting-banned-during-traffic-spikes" aria-label="Permalink to &quot;&quot;Legitimate clients getting banned during traffic spikes&quot;&quot;">​</a></h3><p>Raise <code>syn_pps_threshold</code> and/or lower <code>syn_pps_score</code> so transient bursts don&#39;t cross the suspicion threshold. Whitelist known high-volume sources.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><p><a href="/pingless-studios-docs/openshield-xdp/detection-engine/overview">Detection Engine Overview</a> · <a href="/pingless-studios-docs/openshield-xdp/detection-engine/rate-based">Rate-Based Detection</a> · <a href="/pingless-studios-docs/openshield-xdp/mitigation/overview">Mitigation Overview</a></p>`,16))])}const S=n(h,[["render",g]]);export{f as __pageData,S as default};
